'use strict';
const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
const state={posts:[],category:'Semua',query:'',savedOnly:false,limit:6,sort:'newest',current:null,fontSize:18,quote:0};
const saved=new Set(readSaved());
function readSaved(){try{const v=JSON.parse(localStorage.getItem('cs.saved')||'[]');return Array.isArray(v)?v.filter(x=>typeof x==='string'):[]}catch{return []}}
const imagePath=p=>'/'+p.image.replace(/^\//,'');
const articlePath=p=>'/artikel/'+p.id+'/';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const bookmarkIcon='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4Z"/></svg>';
const dateText=s=>new Date(s+'T12:00:00Z').toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'});
let toastTimer,previousFocus;
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2500)}
function persistSaved(){try{localStorage.setItem('cs.saved',JSON.stringify([...saved]))}catch{toast('Disimpan untuk sesi ini. Penyimpanan browser tidak tersedia.')}$('#savedCount').textContent=saved.size}
function toggleSaved(id){if(saved.has(id)){saved.delete(id);toast('Catatan dihapus dari simpanan.')}else{saved.add(id);toast('Catatan disimpan di perangkatmu.')}persistSaved();renderLibrary();updateReaderSave()}
function updateReaderSave(){if(!state.current)return;const active=saved.has(state.current.id);$('#readerSave').textContent=active?'Tersimpan ✓':'Simpan';$('#readerSave').setAttribute('aria-pressed',String(active))}
function openPost(id){const p=state.posts.find(p=>p.id===id);if(!p)return;if(p.category==='Buku Pilihanmu'){window.open(p.url,'_blank','noopener,noreferrer');return}previousFocus=document.activeElement;state.current=p;$('#readerTitle').textContent=p.title;$('#readerCategory').textContent=p.category;$('#readerMeta').textContent=`Catatan Santri · ${dateText(p.date)} · ${p.minutes} menit baca`;$('#readerImage').src=imagePath(p);$('#readerImage').alt=p.title;$('#readerImage').hidden=!p.image;$('#readerBody').innerHTML=p.html;$('#readerBody').style.fontSize=state.fontSize+'px';$('#readerSource').href=p.url;updateReaderSave();if(!$('#reader').open){$('#reader').showModal();document.body.style.overflow='hidden'}$('#readerScroll').scrollTop=0;$('#readingProgress').style.width='0%';$('#readerClose').focus();history.replaceState(null,'',articlePath(p));$('#shareWhatsapp').href='https://wa.me/?text='+encodeURIComponent(p.title+' '+new URL(articlePath(p),location.origin).href);$('#shareTelegram').href='https://t.me/share/url?url='+encodeURIComponent(new URL(articlePath(p),location.origin).href)+'&text='+encodeURIComponent(p.title)}
function closeReader(){if($('#reader').open)$('#reader').close();document.body.style.overflow='';history.replaceState(null,'','/#catatan');previousFocus?.focus()}
function renderPreview(topic='Muhasabah'){const p=state.posts.find(x=>x.category===topic&&x.category!=='Buku Pilihanmu');if(!p)return;$('#previewContent').innerHTML=`<div class="preview-inner"><div class="preview-category">${esc(p.category)}</div><h3>${esc(p.title)}</h3><img src="${esc(imagePath(p))}" alt="${esc(p.title)}"><p>${esc(p.excerpt)}</p><div class="preview-footer"><span>${p.minutes} MENIT UNTUK DIRIMU</span><button data-open="${p.id}">Baca catatan ↗</button></div></div>`}
function card(p,featured=false){if(featured)return `<a class="feature-card reveal" href="${articlePath(p)}" data-open="${p.id}"><div class="feature-image-wrap"><img src="${esc(imagePath(p))}" alt="${esc(p.title)}" loading="lazy"><span class="feature-arrow" aria-hidden="true">↗</span></div><div class="card-meta"><span class="category-label">${esc(p.category)}</span><span>${p.minutes} menit baca</span></div><h3>${esc(p.title)}</h3><p>${esc(p.excerpt)}</p></a>`;return `<article class="article-card"><a class="article-image-button" href="${articlePath(p)}" data-open="${p.id}" aria-label="Baca ${esc(p.title)}"><img src="${esc(imagePath(p))}" alt="" loading="lazy"></a><button class="bookmark" data-save="${p.id}" aria-label="${saved.has(p.id)?'Hapus dari simpanan':'Simpan'}: ${esc(p.title)}" aria-pressed="${saved.has(p.id)}">${bookmarkIcon}</button><div class="card-meta"><span class="category-label">${esc(p.category)}</span><span>${p.minutes} menit baca</span></div><a class="article-title" href="${articlePath(p)}" data-open="${p.id}">${esc(p.title)}</a><p>${esc(p.excerpt)}</p><div class="article-date"><span>${dateText(p.date)}</span><button data-open="${p.id}" aria-label="Baca ${esc(p.title)}">${p.category==='Buku Pilihanmu'?'Lihat buku ↗':'Baca ↗'}</button></div></article>`}
function filteredPosts(){return state.posts.filter(p=>(state.category==='Semua'||p.category===state.category)&&(!state.savedOnly||saved.has(p.id))&&(!state.query||(p.title+' '+p.text+' '+p.category).toLocaleLowerCase('id').includes(state.query.toLocaleLowerCase('id')))).sort((a,b)=>state.sort==='short'?a.minutes-b.minutes:state.sort==='oldest'?a.date.localeCompare(b.date):b.date.localeCompare(a.date))}
function renderLibrary(){const list=filteredPosts();$('#articleGrid').innerHTML=list.slice(0,state.limit).map(p=>card(p)).join('');$('#resultCount').textContent=`${list.length} ${state.savedOnly?'catatan tersimpan':'catatan'}${state.category!=='Semua'?' · '+state.category:''}`;$('#emptyState').hidden=list.length>0;$('#emptyMessage').textContent=state.savedOnly?'Simpan tulisan dengan ikon penanda di sudut gambar.':'Coba kata kunci lain, atau jelajahi semua kategori.';$('#loadMore').hidden=list.length<=state.limit;$$('.filter').forEach(b=>{const on=b.dataset.category===state.category;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});$('#savedFilter').setAttribute('aria-pressed',String(state.savedOnly));$('#savedCount').textContent=saved.size}
function setCategory(cat){state.category=cat;state.limit=6;state.query='';$('#searchInput').value='';state.savedOnly=false;renderLibrary()}
function renderFeatured(){const wanted=['Percuma Nyantri','Mengenal Diri','Efek Samping','Kemana Kakiku'];const posts=wanted.map(t=>state.posts.find(p=>p.title.startsWith(t))).filter(Boolean);$('#featuredGrid').innerHTML=posts.map(p=>card(p,true)).join('');observeReveals()}
function reset(){state.category='Semua';state.query='';state.savedOnly=false;state.limit=6;$('#searchInput').value='';renderLibrary()}
const quotes=[{text:'Ikhlas bukan berarti seseorang tidak boleh memikirkan masa depan.',label:'TENTANG MASA DEPAN',find:'Santri Setelah Mondok'},{text:'Ta’awun tidak harus berhenti. Bentuknya saja yang bisa berubah.',label:'TENTANG PENGABDIAN',find:'Santri Setelah Mondok'},{text:'Ilmunya santri. Akhlaknya santri. Jiwanya tetap mengabdi. Tetapi ekonominya kuat dan manfaatnya luas.',label:'TENTANG PERJALANAN',find:'Santri Setelah Mondok'}];
function setQuote(i){state.quote=i;$('#quoteText').textContent='“'+quotes[i].text+'”';$('#quoteLabel').textContent=quotes[i].label;$$('[data-quote]').forEach(b=>{const on=Number(b.dataset.quote)===i;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',String(on))})}
let observer;
function observeReveals(){if(!('IntersectionObserver' in window)){document.body.classList.add('no-motion');return}observer??=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.07});$$('.reveal:not(.visible)').forEach(e=>observer.observe(e))}
async function init(){observeReveals();try{const r=await fetch('/posts.json');if(!r.ok)throw Error('Could not load posts');const data=await r.json();state.posts=data.posts;const categories=[...new Set(state.posts.map(p=>p.category))];const ordered=['Semua','Muhasabah','Growth Mindset','Parenting','Keluarga','Kisah Salaf','Masa Depan','Buku Pilihanmu'].filter(c=>c==='Semua'||categories.includes(c));$('#filters').innerHTML=ordered.map(c=>`<button class="filter${c==='Semua'?' active':''}" data-category="${esc(c)}" aria-pressed="${c==='Semua'}">${c==='Buku Pilihanmu'?'Buku Pilihan':esc(c)}</button>`).join('');$('#totalStat').textContent=state.posts.length;$('#categoryStat').textContent=categories.length;renderPreview();renderFeatured();renderLibrary();if(location.hash.startsWith('#artikel=')){const id=decodeURIComponent(location.hash.slice(9));openPost(id)}}catch(e){$('#loadError').hidden=false;$('#resultCount').textContent='Catatan belum tersedia.';$('#loadMore').hidden=true;console.error(e)}}
function closeMenu(){ $('#mobileMenu').hidden=true;$('#menuButton').setAttribute('aria-expanded','false')}
$('#menuButton').addEventListener('click',()=>{const open=$('#mobileMenu').hidden;$('#mobileMenu').hidden=!open;$('#menuButton').setAttribute('aria-expanded',String(open))});
$('#mobileMenu').addEventListener('click',e=>{if(e.target.closest('a'))closeMenu()});
$('#navSearch').addEventListener('click',()=>{closeMenu();$('#catatan').scrollIntoView({behavior:'smooth'});$('#searchInput').focus({preventScroll:true})});
window.addEventListener('scroll',()=>$('#header').classList.toggle('fixed',window.scrollY>38),{passive:true});
window.addEventListener('resize',()=>{if(innerWidth>820)closeMenu()});
document.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(open){if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();openPost(open.dataset.open);return}const save=e.target.closest('[data-save]');if(save){toggleSaved(save.dataset.save);return}const filter=e.target.closest('[data-category]');if(filter){setCategory(filter.dataset.category);return}const link=e.target.closest('[data-filter-link]');if(link){setCategory(link.dataset.filterLink);closeMenu()}const topic=e.target.closest('[data-topic]');if(topic){$$('.topic').forEach(b=>{const on=b===topic;b.classList.toggle('active',on);b.setAttribute('aria-expanded',String(on));b.querySelector('.topic-plus').textContent=on?'−':'+'});renderPreview(topic.dataset.topic)}const quote=e.target.closest('[data-quote]');if(quote)setQuote(Number(quote.dataset.quote))});
$('#searchInput').addEventListener('input',e=>{state.query=e.target.value.trim();state.limit=6;renderLibrary()});$('#sortSelect').addEventListener('change',e=>{state.sort=e.target.value;renderLibrary()});$('#savedFilter').addEventListener('click',()=>{state.savedOnly=!state.savedOnly;state.limit=6;renderLibrary()});$('#loadMore').addEventListener('click',()=>{state.limit+=6;renderLibrary()});$('#resetFilters').addEventListener('click',reset);
$('#quoteRead').addEventListener('click',()=>{const p=state.posts.find(x=>x.title.startsWith(quotes[state.quote].find));if(p)openPost(p.id)});
$('#readerClose').addEventListener('click',closeReader);$('#readerBack').addEventListener('click',e=>{e.preventDefault();closeReader()});$('#reader').addEventListener('cancel',e=>{e.preventDefault();closeReader()});$('#readerSave').addEventListener('click',()=>{if(state.current)toggleSaved(state.current.id)});
function changeFont(delta){state.fontSize=Math.min(24,Math.max(14,state.fontSize+delta));$('#readerBody').style.fontSize=state.fontSize+'px';$('#fontDown').disabled=state.fontSize===14;$('#fontUp').disabled=state.fontSize===24}
$('#fontDown').addEventListener('click',()=>changeFont(-1));$('#fontUp').addEventListener('click',()=>changeFont(1));$('#readerNext').addEventListener('click',()=>{const readable=state.posts.filter(x=>x.category!=='Buku Pilihanmu');const index=readable.findIndex(p=>p.id===state.current?.id);if(readable.length)openPost(readable[(index+1)%readable.length].id)});
$('#readerScroll').addEventListener('scroll',e=>{const el=e.target;const max=el.scrollHeight-el.clientHeight;$('#readingProgress').style.width=(max>0?Math.min(100,el.scrollTop/max*100):0)+'%'},{passive:true});
$('#privacyButton').addEventListener('click',()=>$('#privacyDialog').showModal());$('#privacyClose').addEventListener('click',()=>$('#privacyDialog').close());$('#clearSaved').addEventListener('click',()=>{saved.clear();persistSaved();renderLibrary();updateReaderSave();toast('Semua catatan tersimpan telah dihapus.')});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#reader').open&&!$('#privacyDialog').open){e.preventDefault();$('#catatan').scrollIntoView({behavior:'smooth'});$('#searchInput').focus({preventScroll:true})}if(e.key==='Escape')closeMenu()});
window.addEventListener('popstate',()=>{if($('#reader').open)closeReader()});
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#artikel='))openPost(decodeURIComponent(location.hash.slice(9)));else if($('#reader').open)closeReader()});
$('#shareCopy').addEventListener('click',async()=>{if(!state.current)return;const url=new URL(articlePath(state.current),location.origin).href;try{await navigator.clipboard.writeText(url);$('#shareCopy').textContent='Tautan disalin ✓';setTimeout(()=>$('#shareCopy').textContent='Salin tautan ↗',1800)}catch{$('#shareCopy').textContent='Salin dari alamat browser';toast('Salin tautan dari alamat browser di atas.')}});
$('#year').textContent=new Date().getFullYear();init();
